'use client'

import Link from 'next/link'
import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase/client'
import { getUserRole } from '@/lib/supabase/roles'
import type { VendorIntegration } from '@/lib/vendor/integrations'
import { vendorIntegrationService } from '@/lib/vendor/integrations'
import { CatalogFeedback } from '../components/CatalogFeedback'
import { IntegrationStatusBadge } from '../components/IntegrationStatusBadge'

export default function VendorIntegrationsPage() { const [integrations, setIntegrations] = useState<VendorIntegration[]>([]); const [loading, setLoading] = useState(true); useEffect(() => { void createClient().auth.getUser().then(async ({ data: { user } }) => { if (user && (getUserRole(user) === 'vendor' || getUserRole(user) === 'admin')) setIntegrations(await vendorIntegrationService.list(user.id)); setLoading(false) }) }, []); if (loading) return <main className="vendor-page"><div className="operations-shell"><CatalogFeedback type="loading">Loading integrations...</CatalogFeedback></div></main>; return <main className="vendor-page"><header className="vendor-header"><Link href="/vendor" className="logo logo-active">Furnish<span>AI</span></Link><nav><Link href="/vendor/products" className="btn-skip">Catalog</Link><span className="vendor-header-label">Integrations</span></nav></header><div className="operations-shell"><div className="operations-heading"><div><p className="vendor-eyebrow">Vendor portal / Phase 09</p><h1>External integrations</h1><p>Connect an external catalog when your authentication and payload mapping requirements are ready.</p></div></div><section className="integration-architecture"><p className="vendor-eyebrow">Integration architecture</p><h2>Provider-neutral by design.</h2><p>Each provider will supply authentication, mapping, validation, webhook verification, and synchronization adapters. The core catalog and approval workflow remain unchanged.</p><div className="integration-flow"><span>Vendor system</span><b>→</b><span>Auth</span><b>→</b><span>Validate</span><b>→</b><span>Map</span><b>→</b><span>Catalog + approval</span></div></section>{integrations.length ? <div className="integration-list">{integrations.map((integration) => <article className="integration-card" key={integration.id}><div><p className="vendor-eyebrow">{integration.providerKey}</p><h2>{integration.displayName}</h2><p>{integration.domains.join(', ')} · {integration.direction}</p></div><IntegrationStatusBadge status={integration.status} /><div><small>Last sync: {integration.lastSyncAt ? new Date(integration.lastSyncAt).toLocaleString('en-IN') : 'Never'}</small></div></article>)}</div> : <div className="operations-empty"><h2>No integrations configured</h2><p>No authentication protocol or external payload contract has been selected yet.</p></div>}<p className="operations-note">Credentials must be stored server-side by reference. Never expose vendor secrets, access tokens, or webhook signing material to this client.</p></div></main> }